function mount3d(el,mode,opt={}){
 if(!window.THREE){el.innerHTML='<p style="padding:24px">Visualiseur 3D indisponible hors-ligne.</p>';return}
 const w=el.clientWidth||400,h=el.clientHeight||340,r=new THREE.WebGLRenderer({antialias:true,alpha:true});r.setSize(w,h);r.setPixelRatio(Math.min(devicePixelRatio,2));el.appendChild(r.domElement);
 const s=new THREE.Scene(),c=new THREE.PerspectiveCamera(40,w/h,.1,100),g=new THREE.Group(),Z=mode=='bim'?9:5;c.position.z=Z;s.add(g,new THREE.AmbientLight(0xffffff,.65));const L=new THREE.DirectionalLight(0xffffff,.9);L.position.set(3,5,4);s.add(L);
 const mk=(geo,col)=>new THREE.Mesh(geo,new THREE.MeshStandardMaterial({color:col,metalness:.2,roughness:.45,flatShading:true}));
 const a={g,meshes:[],auto:!matchMedia('(prefers-reduced-motion:reduce)').matches,mk};
 if(mode=='prism'){a.main=mk(new THREE.CylinderGeometry(1,1,1.5,6),0x1F89C5);g.add(a.main);g.rotation.x=.5}
 else{[0x9aa7b8,0x1F89C5,0x169999].forEach(()=>0);for(let f=0;f<4;f++){const y=f*1.1-1.6,sl=mk(new THREE.BoxGeometry(4,.12,3),0x9aa7b8),wl=mk(new THREE.BoxGeometry(3.6,.9,2.6),0x1F89C5),rs=mk(new THREE.BoxGeometry(3.4,.08,.14),0x169999);sl.position.y=y;wl.position.y=y+.51;rs.position.y=y+.9;wl.material.transparent=true;wl.material.opacity=.7;sl.userData={n:'Dalle — niveau '+f,cat:0,mat:'Béton'};wl.userData={n:'Murs — niveau '+f,cat:1,mat:'Brique'};rs.userData={n:'Gaine technique — niveau '+f,cat:2,mat:'Acier'};g.add(sl,wl,rs);a.meshes.push(sl,wl,rs)}g.rotation.x=.45}
 let d=0,px=0,py=0,mv=0;const cv=r.domElement,rc=new THREE.Raycaster();
 cv.onpointerdown=e=>{d=1;a.auto=false;px=e.clientX;py=e.clientY;mv=0;cv.setPointerCapture(e.pointerId)};
 cv.onpointermove=e=>{if(!d)return;g.rotation.y+=(e.clientX-px)*.01;g.rotation.x+=(e.clientY-py)*.01;mv+=Math.abs(e.clientX-px)+Math.abs(e.clientY-py);px=e.clientX;py=e.clientY};
 cv.onpointerup=e=>{d=0;if(mode=='bim'&&mv<5){const b=cv.getBoundingClientRect();rc.setFromCamera({x:(e.clientX-b.left)/b.width*2-1,y:-((e.clientY-b.top)/b.height)*2+1},c);const hit=rc.intersectObjects(a.meshes.filter(m=>m.visible))[0];a.meshes.forEach(m=>m.material.emissive.setHex(0));if(hit){hit.object.material.emissive.setHex(0x113355);opt.pick&&opt.pick(hit.object.userData)}}};
 cv.onwheel=e=>{e.preventDefault();c.position.z=Math.min(14,Math.max(2.5,c.position.z+e.deltaY*.005))};
 a.reset=()=>{g.rotation.set(.45,0,0);c.position.z=Z};
 (function loop(){raf=requestAnimationFrame(loop);if(a.auto)g.rotation.y+=.006;r.render(s,c)})();a.dispose=()=>{cancelAnimationFrame(raf);g.traverse(o=>{o.geometry&&o.geometry.dispose();o.material&&o.material.dispose()});r.dispose();r.forceContextLoss();r.domElement.remove()};return a}
